import React, { useState } from 'react';
import './App.css';
import ImageProcessor from './components/ImageProcessor';
import VideoProcessor from './components/VideoProcessor';
import CameraProcessor from './components/CameraProcessor';
import History from './components/History';

function App() {
  const [activeTab, setActiveTab] = useState('image');
  const [colorblindType, setColorblindType] = useState('protanopia');
  const [mode, setMode] = useState('simulate');

  return (
    <div className="App">
      <header className="App-header">
        <h1>Color Blindness Friendly Filter</h1>
        <p>Process images, videos, and live camera feed for color blindness accessibility</p>
      </header>

      <div className="controls">
        <div className="control-group">
          <label>Color Blindness Type:</label>
          <select 
            value={colorblindType} 
            onChange={(e) => setColorblindType(e.target.value)}
          >
            <option value="protanopia">Protanopia (Red-blind)</option>
            <option value="deuteranopia">Deuteranopia (Green-blind)</option>
            <option value="tritanopia">Tritanopia (Blue-blind)</option>
          </select>
        </div>

        <div className="control-group">
          <label>Mode:</label>
          <select 
            value={mode} 
            onChange={(e) => setMode(e.target.value)}
          >
            <option value="simulate">Simulate Color Blindness</option>
            <option value="enhance">Enhance for Color Blind</option>
          </select>
        </div>
      </div>

      <div className="tabs">
        <button 
          className={activeTab === 'image' ? 'active' : ''}
          onClick={() => setActiveTab('image')}
        >
          Image
        </button>
        <button 
          className={activeTab === 'video' ? 'active' : ''}
          onClick={() => setActiveTab('video')}
        >
          Video
        </button>
        <button 
          className={activeTab === 'camera' ? 'active' : ''}
          onClick={() => setActiveTab('camera')}
        >
          Live Camera
        </button>
        <button 
          className={activeTab === 'history' ? 'active' : ''}
          onClick={() => setActiveTab('history')}
        >
          History
        </button>
      </div>

      <div className="content">
        {activeTab === 'image' && (
          <ImageProcessor colorblindType={colorblindType} mode={mode} />
        )}
        {activeTab === 'video' && (
          <VideoProcessor colorblindType={colorblindType} mode={mode} />
        )}
        {activeTab === 'camera' && (
          <CameraProcessor colorblindType={colorblindType} mode={mode} />
        )}
        {activeTab === 'history' && <History />}
      </div>
    </div>
  );
}

export default App;
